    out attribute serial_0_trigger : Boolean = pollTimerMs >= 3000;
    out attribute serial_0_value_0 : Real = io_1;
    out attribute serial_0_value_1 : Real = io_4;
    out attribute serial_1_trigger : Boolean = pollTimerMs >= 3000 and distanceBelowCount >= 3;
    out attribute serial_1_value_0 : Boolean = distanceBelowCount >= 3;
